13	type Scenario = {
14	  customer: Customer;
15	  steps: { items: Item[] }[];
16	};
17	
18	const PROCESSING_FEE = 5;
19	const FIRST_INSURANCE_SURCHARGE = 0.1;
20	const CURSE_SURCHARGE = 0.5;
21	const HIGH_ENCHANTMENT_THRESHOLD = 5;
22	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
23	const LOYALTY_THRESHOLD_YEARS = 2;
24	const LOYALTY_DISCOUNT = 0.2;
25	
26	const BASE_PREMIUMS: Record<string, number> = {
27	  sword: 100,
28	  amulet: 60,
29	  staff: 80,
30	  potion: 40,
31	  rune: 25,
32	  moonstone: 25,
33	};
34	
35	const ALIKE_BLOCK_SIZE = 3;
36	const ALIKE_BLOCK_PREMIUM = 60;
37	
38	type AlikeGroup = [type: string, count: number];
39	
40	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
41	  const countByType = new Map<string, number>();
42	
43	  for (const item of items) {
44	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
45	  }
46	
47	  return [...countByType];
48	};
49	
50	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
51	
52	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
53	
54	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
55	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
56	
57	  return count * basePremiumOfType(type);
58	};
59	
60	/**
61	 * The policy base premium: the sum of the item base premiums, with the
62	 * alike-block discount applied. Policy-scope modifiers are percentages OF
63	 * THIS amount — never of a total that already includes item surcharges.
64	 */
65	const policyBasePremiumOf = (items: Item[]): number =>
66	  groupAlikeItems(items)
67	    .map(basePremiumOfGroup)
68	    .reduce((total, groupPremium) => total + groupPremium, 0);
69	
70	/**
71	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
72	 * premium, independent of the policy base and of the alike-block discount.
73	 */
74	const isCursed = (item: Item): boolean => item.cursed === true;
75	
76	const isHighlyEnchanted = (item: Item): boolean =>
77	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
78	
79	const surchargeRateOf = (item: Item): number =>
80	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
81	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
82	
83	const itemSurchargesOf = (items: Item[]): number =>
84	  items.reduce((total, item) => total + ownBasePremiumOf(item) * surchargeRateOf(item), 0);
85	
86	/**
87	 * Policy-scope surcharges: each is a percentage of the policy base premium.
88	 */
89	const isLongStanding = (customer: Customer): boolean =>
90	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
91	
92	const policyModifierRateOf = (customer: Customer): number =>
93	  FIRST_INSURANCE_SURCHARGE - (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0);
94	
95	const policySurchargesOn = (policyBase: number, customer: Customer): number =>
96	  policyBase * policyModifierRateOf(customer);
97	
98	const quotePremium = (items: Item[], customer: Customer): number => {
99	  const policyBase = policyBasePremiumOf(items);
100	  const premium =
101	    policyBase +
102	    itemSurchargesOf(items) +
103	    policySurchargesOn(policyBase, customer) +
104	    PROCESSING_FEE;
105	
106	  return Math.ceil(premium);
107	};
108	
109	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
110	  results: scenario.steps.map((step) => ({
111	    premium: quotePremium(step.items, scenario.customer),
112	  })),
113	});
